from importlib import import_module
from inspect import getmembers, isclass
from typing import Dict, Any, Optional, Tuple
from tools.base import BaseTool
import json

class ToolExecutionResult:
    """Result container for tool execution with structured data."""
    def __init__(self, success: bool, data: Any = None, error: Optional[str] = None):
        self.success = success
        self.data = data
        self.error = error

    def to_dict(self) -> Dict[str, Any]:
        """Convert to dictionary representation."""
        return {
            "success": self.success,
            "data": self.data,
            "error": self.error
        }

    def __str__(self) -> str:
        if self.success:
            return json.dumps(self.data, default=str) if isinstance(self.data, (dict, list)) else str(self.data)
        return f"Error: {self.error}"

class ToolExecutor:
    """Executes tools by name using dynamic import and instantiation."""

    # Cache tool classes after first discovery
    _tool_cache: Dict[str, type] = {}

    def __init__(self, tools_package: str = "tools"):
        self.tools_package = tools_package
        self._discover_tools()

    def _discover_tools(self):
        """Pre-load tool classes to enable caching and reuse."""
        try:
            tools_module = import_module(self.tools_package)
            for _, module_name, is_pkg in pkgutil.iter_modules(tools_module.__path__):
                if is_pkg or module_name == 'base':
                    continue
                try:
                    module = import_module(f"{self.tools_package}.{module_name}")
                    for _, obj in getmembers(module, lambda x: isclass(x) and issubclass(x, BaseTool) and x is not BaseTool):
                        # Cache by the tool's name property
                        try:
                            instance = obj()
                            if isinstance(instance, BaseTool):
                                ToolExecutor._tool_cache[instance.name] = obj
                        except Exception:
                            pass  # Skip tools that fail to instantiate
                except Exception:
                    pass  # Skip modules that fail to import
        except Exception:
            pass  # Tool discovery failures are non-fatal

    def execute(self, tool_name: str, input_data: Dict[str, Any]) -> ToolExecutionResult:
        """Execute a tool by name with the given input data."""
        try:
            # Use cached class if available, otherwise import fresh
            tool_class = ToolExecutor._tool_cache.get(tool_name)

            if not tool_class:
                try:
                    module = import_module(f"{self.tools_package}.{tool_name}")
                    for _, obj in getmembers(module, lambda x: isclass(x) and issubclass(x, BaseTool) and x is not BaseTool):
                        tool_class = obj
                        break

                    if not tool_class:
                        return ToolExecutionResult(False, error=f"Tool class not found for '{tool_name}'")

                    # Cache the discovered class for future use
                    instance = tool_class()
                    ToolExecutor._tool_cache[tool_name] = tool_class
                except Exception as e:
                    return ToolExecutionResult(False, error=f"Failed to import tool '{tool_name}': {str(e)}")
            else:
                try:
                    instance = tool_class()
                except Exception as e:
                    return ToolExecutionResult(False, error=f"Failed to instantiate tool '{tool_name}': {str(e)}")

            # Execute the tool
            try:
                result = instance.execute(**input_data)
                return ToolExecutionResult(True, data=result)
            except Exception as e:
                return ToolExecutionResult(False, error=f"Error executing '{tool_name}': {str(e)}")

        except Exception as e:
            return ToolExecutionResult(False, error=f"Unexpected error executing '{tool_name}': {str(e)}")

    @staticmethod
    def clean_data_for_display(data: Any) -> Any:
        """Recursively clean data for display, omitting base64 content."""
        if isinstance(data, str):
            if len(data) > 1000 and (';base64,' in data or data.startswith('data:')):
                return "[base64 data omitted]"
            return data
        elif isinstance(data, dict):
            cleaned = {}
            for key, value in data.items():
                if key in ['data', 'image', 'source'] and isinstance(value, str):
                    if len(value) > 1000 and (';base64,' in value or value.startswith('data:')):
                        cleaned[key] = "[base64 data omitted]"
                    else:
                        cleaned[key] = value
                else:
                    cleaned[key] = ToolExecutor.clean_data_for_display(value)
            return cleaned
        elif isinstance(data, list):
            return [ToolExecutor.clean_data_for_display(item) for item in data]
        return data
